/**
 * Form spam protection for the Elementor (V4) forms, without a plugin or captcha.
 * Each form carries two visually hidden fields:
 *  - tmc-hp-website: a honeypot people never see; bots fill it in.
 *  - tmc-hp-ts: the page render time (Current Date Time dynamic tag, Unix format); submissions under 3s are bots. date_i18n() matches the tag's clock.
 */
add_filter( 'elementor_pro/atomic_forms/spam_check', function ( $is_spam, $form_fields ) {
	if ( $is_spam ) {
		return true;
	}
	foreach ( (array) $form_fields as $field ) {
		// The hidden fields have no label or placeholder, so the form script posts their CSS ID as the label.
		$name  = is_array( $field ) ? (string) ( $field['label'] ?? '' ) : '';
		$value = is_array( $field ) ? trim( (string) ( $field['value'] ?? '' ) ) : '';
		if ( 'tmc-hp-website' === $name && '' !== $value ) {
			return true;
		}
		if ( 'tmc-hp-ts' === $name && ( ! ctype_digit( $value ) || (int) date_i18n( 'U' ) - (int) $value < 3 ) ) {
			return true;
		}
	}
	return false;
}, 20, 2 );

// Keep the hidden spam-check fields out of notification emails.
add_filter( 'elementor_pro/atomic_forms/email_message', function ( $message ) {
	return preg_replace( '/^tmc-hp-(website|ts):[^\n]*(\n|<br>)?/mi', '', (string) $message );
} );

/**
 * TMC: Mat & Accessory Content
 * Shortcodes used by the Single Mat and Single Accessory templates.
 * Data comes from the ACF groups "Mat Details" and "Accessory Details".
 *
 * [tmc_breadcrumbs]       Home / Products / Category / Title
 * [tmc_mat_badges]        Traffic, use and Mat Finder chips
 * [tmc_mat_specs]         Specification table (empty rows hidden)
 * [tmc_mat_options]       Design options: feature image + up to 3 galleries
 * [tmc_mat_references]    Reference sites list + images
 * [tmc_gallery field=""]  Any gallery field as a grid
 * [tmc_downloads]         Download buttons from the Downloads field
 * [tmc_projects slugs=""] Project cards from page slugs
 * [tmc_related]           Other items of the same type / category
 * [tmc_summary]           The summary text
 * [tmc_cards type="" term=""] Grid of mats or accessories
 */
if (!function_exists('tmc_field')) {

	function tmc_field($name, $id = null) {
		$id = $id ?: get_the_ID();
		// Raw (unformatted) values: galleries keep their [gallery] shortcode, images stay IDs.
		return function_exists('get_field') ? get_field($name, $id, false) : get_post_meta($id, $name, true);
	}

	function tmc_gallery_ids($value) {
		if (preg_match('/ids="([\d,\s]+)"/', (string) $value, $m)) return array_filter(array_map('intval', explode(',', $m[1])));
		return [];
	}

	function tmc_gallery_html($ids, $group, $captions = true) {
		if (!$ids) return '';
		$out = '<div class="tmc-m-gallery">';
		foreach ($ids as $id) {
			$full = wp_get_attachment_image_url($id, 'large');
			if (!$full) continue;
			$title = get_the_title($id);
			$caption = wp_get_attachment_caption($id) ?: $title;
			$out .= '<figure class="tmc-m-gallery__item"><a href="' . esc_url($full) . '" data-elementor-open-lightbox="yes" data-elementor-lightbox-slideshow="' . esc_attr($group) . '" data-elementor-lightbox-title="' . esc_attr($caption) . '">'
				. wp_get_attachment_image($id, 'medium_large', false, ['loading' => 'lazy', 'alt' => get_post_meta($id, '_wp_attachment_image_alt', true) ?: $caption])
				. '</a>' . ($captions ? '<figcaption>' . esc_html($caption) . '</figcaption>' : '') . '</figure>';
		}
		return $out . '</div>';
	}

	function tmc_section($title, $body, $eyebrow = '', $mod = '') {
		if (trim($body) === '') return '';
		$head = $eyebrow ? '<p class="tmc-m-eyebrow">' . esc_html($eyebrow) . '</p>' : '';
		$head .= $title ? '<h2 class="tmc-m-h2">' . esc_html($title) . '</h2>' : '';
		return '<section class="tmc-m-section ' . esc_attr($mod) . '"><div class="tmc-m-container">' . ($head ? '<div class="tmc-m-head">' . $head . '</div>' : '') . $body . '</div></section>';
	}

	function tmc_join($v) { return is_array($v) ? implode(', ', array_filter($v)) : trim((string) $v); }

	add_shortcode('tmc_summary', function ($atts) {
		$a = shortcode_atts(['words' => 0], $atts);
		$s = tmc_field('tmc_summary');
		if ($s && (int) $a['words']) return esc_html(wp_trim_words($s, (int) $a['words']));
		return $s ? nl2br(esc_html(trim($s))) : '';
	});

	add_shortcode('tmc_breadcrumbs', function () {
		$items = ['<a href="' . esc_url(home_url('/')) . '">Home</a>'];
		if (is_singular('mats')) {
			$items[] = '<a href="' . esc_url(home_url('/products/')) . '">Products</a>';
			$terms = get_the_terms(get_the_ID(), 'mat-categories');
			if ($terms && !is_wp_error($terms)) {
				$page = get_page_by_path($terms[0]->slug);
				$items[] = '<a href="' . esc_url($page ? get_permalink($page) : get_term_link($terms[0])) . '">' . esc_html($terms[0]->name) . '</a>';
			}
		} elseif (is_singular('accessories-frames')) {
			$items[] = '<a href="' . esc_url(home_url('/products/')) . '">Products</a>';
			$items[] = '<a href="' . esc_url(home_url('/frames-and-accessories/')) . '">Frames &amp; Accessories</a>';
		} elseif (is_singular('page') && tmc_field('tmc_is_project')) {
			$items[] = '<a href="' . esc_url(home_url('/reference-sites/')) . '">Projects</a>';
		} elseif (is_singular('post')) {
			$items[] = '<a href="' . esc_url(home_url('/matting-matters/')) . '">Matting Matters</a>';
		} elseif (is_tax('mat-categories')) {
			$items[] = '<a href="' . esc_url(home_url('/products/')) . '">Products</a>';
		}
		$current = is_tax() || is_category() || is_tag() ? single_term_title('', false) : (is_post_type_archive() ? post_type_archive_title('', false) : (is_search() ? 'Search' : get_the_title()));
		$items[] = '<span aria-current="page">' . esc_html($current) . '</span>';
		return '<span class="tmc-m-crumbs" role="navigation" aria-label="Breadcrumb">' . implode('<span class="tmc-m-crumbs__sep" aria-hidden="true">/</span>', $items) . '</span>';
	});

	add_shortcode('tmc_mat_badges', function () {
		$chips = [];
		foreach ((array) tmc_field('tmc_wear') as $w) if ($w) $chips[] = ['Traffic', $w];
		if ($u = tmc_field('tmc_use')) $chips[] = ['Use', $u];
		if ($f = array_filter((array) tmc_field('tmc_mat_finder'))) $chips[] = ['Mat Finder', 'Category ' . implode(' & ', $f)];
		if (!$chips) return '';
		$out = '<span class="tmc-m-badges">';
		foreach ($chips as $c) $out .= '<span class="tmc-m-badge"><span>' . esc_html($c[0]) . '</span>' . esc_html($c[1]) . '</span>';
		return $out . '</span>';
	});

	add_shortcode('tmc_mat_specs', function () {
		$stars = function ($n) { $n = (int) $n; return $n ? '<span class="tmc-m-stars" aria-label="' . $n . ' out of 5">' . str_repeat('★', $n) . '<span>' . str_repeat('★', 5 - $n) . '</span></span>' : ''; };
		$rows = [
			'Supplied by'      => esc_html('The Matting Company'),
			'Product'          => esc_html(get_the_title()),
			'Height'           => esc_html(tmc_join(tmc_field('tmc_height'))),
			'Available sizes'  => esc_html(tmc_join(tmc_field('tmc_sizes'))),
			'Insert type'      => esc_html(tmc_join(tmc_field('tmc_insert'))),
			'Water absorption' => $stars(tmc_field('tmc_water_absorption')),
			'Design'           => esc_html(tmc_join(tmc_field('tmc_design'))),
			'Fire rating'      => esc_html(tmc_field('tmc_fire_rating')),
			'Wear'             => esc_html(tmc_join(tmc_field('tmc_wear'))),
			'Guarantee'        => esc_html(tmc_field('tmc_guarantee')),
			'Lead time'        => esc_html(tmc_field('tmc_lead_time')),
		];
		$out = '<dl class="tmc-m-specs">';
		foreach ($rows as $label => $val) {
			if ($val === '' || $val === 'N/A') continue;
			$out .= '<div><dt>' . esc_html($label) . '</dt><dd>' . $val . '</dd></div>';
		}
		return $out . '</dl>';
	});

	add_shortcode('tmc_mat_options', function () {
		$body = '';
		$img = (int) tmc_field('tmc_options_image');
		foreach ([1, 2, 3] as $n) {
			$ids = tmc_gallery_ids(tmc_field('tmc_gallery_' . $n));
			if (!$ids) continue;
			$h = tmc_field('tmc_gallery_' . $n . '_heading');
			$body .= '<div class="tmc-m-optgroup">' . ($h ? '<h3 class="tmc-m-h3">' . esc_html(trim($h)) . '</h3>' : '') . tmc_gallery_html($ids, 'options-' . $n) . '</div>';
		}
		if (!$body) return '';
		if ($img) $body = '<div class="tmc-m-options">' . '<div class="tmc-m-options__media">' . wp_get_attachment_image($img, 'large', false, ['loading' => 'lazy']) . '</div><div class="tmc-m-options__groups">' . $body . '</div></div>';
		return tmc_section('Design options', $body, 'Colours & finishes', 'tmc-m-section--surface');
	});

	add_shortcode('tmc_mat_references', function () {
		$list = trim(wp_strip_all_tags((string) tmc_field('tmc_reference_list'), false));
		$names = array_filter(array_map('trim', preg_split('/\R+/', $list)));
		$ids = tmc_gallery_ids(tmc_field('tmc_reference_images'));
		if (!$names && !$ids) return '';
		$body = '';
		if ($names) {
			$body .= '<ul class="tmc-m-chips">';
			foreach ($names as $n) $body .= '<li>' . esc_html($n) . '</li>';
			$body .= '</ul>';
		}
		$body .= tmc_gallery_html($ids, 'references', false);
		return tmc_section('Where it’s installed', $body, 'Reference sites');
	});

	add_shortcode('tmc_gallery', function ($atts) {
		$a = shortcode_atts(['field' => 'tmc_gallery_1', 'title' => '', 'eyebrow' => ''], $atts);
		$html = tmc_gallery_html(tmc_gallery_ids(tmc_field($a['field'])), $a['field']);
		return $a['title'] ? tmc_section($a['title'], $html, $a['eyebrow']) : $html;
	});

	add_shortcode('tmc_downloads', function ($atts) {
		$a = shortcode_atts(['title' => 'Downloads', 'eyebrow' => 'Technical documents'], $atts);
		$raw = (string) tmc_field('tmc_downloads');
		if (!preg_match_all('#<a[^>]+href="([^"]+)"[^>]*>(.*?)</a>#is', $raw, $m, PREG_SET_ORDER)) return '';
		$out = '<ul class="tmc-m-downloads">';
		foreach ($m as $l) {
			$ext = strtoupper(pathinfo(parse_url($l[1], PHP_URL_PATH), PATHINFO_EXTENSION)) ?: 'LINK';
			$out .= '<li><a href="' . esc_url($l[1]) . '" target="_blank" rel="noopener"><span class="tmc-m-downloads__type">' . esc_html($ext) . '</span><span class="tmc-m-downloads__name">' . esc_html(wp_strip_all_tags(html_entity_decode($l[2]))) . '</span><span class="tmc-m-downloads__go" aria-hidden="true">↓</span></a></li>';
		}
		return tmc_section($a['title'], $out . '</ul>', $a['eyebrow'], 'tmc-m-section--surface');
	});

	function tmc_card($id, $kicker = '') {
		$img = get_the_post_thumbnail($id, 'medium_large', ['loading' => 'lazy']);
		if (!$img && preg_match('/wp-image-(\d+)/', (string) get_post_field('post_content', $id), $mm)) {
			$img = wp_get_attachment_image((int) $mm[1], 'medium_large', false, ['loading' => 'lazy']);
		}
		$text = in_array(get_post_type($id), ['mats', 'accessories-frames'], true) ? tmc_field('tmc_summary', $id) : '';
		$text = wp_trim_words(wp_strip_all_tags((string) $text), 22);
		return '<a class="tmc-m-card" href="' . esc_url(get_permalink($id)) . '">'
			. '<span class="tmc-m-card__media">' . ($img ?: '<span class="tmc-m-card__ph"></span>') . '</span>'
			. '<span class="tmc-m-card__body">' . ($kicker ? '<span class="tmc-m-card__kicker">' . esc_html($kicker) . '</span>' : '')
			. '<span class="tmc-m-card__title">' . esc_html(get_the_title($id)) . '</span>'
			. ($text ? '<span class="tmc-m-card__text">' . esc_html($text) . '</span>' : '')
			. '<span class="tmc-m-card__more">' . (get_post_type($id) === 'page' ? 'View project' : 'View details') . ' →</span></span></a>';
	}

	add_shortcode('tmc_cards', function ($atts) {
		$a = shortcode_atts(['type' => 'mats', 'term' => '', 'exclude' => '', 'limit' => -1, 'columns' => 3], $atts);
		$q = ['post_type' => $a['type'], 'posts_per_page' => (int) $a['limit'], 'orderby' => 'menu_order title', 'order' => 'ASC', 'post__not_in' => array_filter([(int) $a['exclude']])];
		if ($a['term']) $q['tax_query'] = [['taxonomy' => 'mat-categories', 'field' => 'slug', 'terms' => explode(',', $a['term'])]];
		$posts = get_posts($q);
		if (!$posts) return '';
		$out = '<div class="tmc-m-cards tmc-m-cards--' . (int) $a['columns'] . '">';
		foreach ($posts as $p) {
			$kicker = '';
			if ($a['type'] === 'mats') { $t = get_the_terms($p->ID, 'mat-categories'); $kicker = $t && !is_wp_error($t) ? $t[0]->name : ''; }
			$out .= tmc_card($p->ID, $kicker);
		}
		return $out . '</div>';
	});

	add_shortcode('tmc_related', function () {
		$id = get_the_ID();
		$type = get_post_type($id);
		$term = '';
		if ($type === 'mats') { $t = get_the_terms($id, 'mat-categories'); $term = $t && !is_wp_error($t) ? $t[0]->slug : ''; }
		$html = do_shortcode('[tmc_cards type="' . esc_attr($type) . '" term="' . esc_attr($term) . '" exclude="' . $id . '" limit="3"]');
		return tmc_section($type === 'mats' ? 'You may also like' : 'More frames & accessories', $html, 'Related');
	});

	add_shortcode('tmc_projects', function ($atts) {
		$a = shortcode_atts(['slugs' => 'apple,boots,montenotte-hotel,capital-docks', 'title' => 'Recent projects', 'eyebrow' => 'Our work'], $atts);
		$out = '';
		foreach (explode(',', $a['slugs']) as $slug) {
			$p = get_page_by_path(trim($slug));
			if (!$p || $p->post_status !== 'publish') continue;
			$out .= tmc_card($p->ID, 'Project');
		}
		if (!$out) return '';
		$out = '<div class="tmc-m-cards tmc-m-cards--4">' . $out . '</div><p class="tmc-m-more"><a href="' . esc_url(home_url('/reference-sites/')) . '">See all projects →</a></p>';
		return tmc_section($a['title'], $out, $a['eyebrow']);
	});

	add_shortcode('tmc_search_title', function () {
		return 'Search results for “' . esc_html(get_search_query()) . '”';
	});

	/**
	 * The Post Content slot of the Single Mat / Single Accessory templates prints the
	 * sections below the hero. Mats and accessories have no editor text, so this is
	 * the whole body; any editor text the post does have is kept and shown first.
	 */
	add_filter('the_content', function ($content) {
		static $busy = false;
		if ($busy || is_admin() || !is_singular(['mats', 'accessories-frames']) || get_the_ID() !== get_queried_object_id()) return $content;
		$busy = true;
		$html = trim($content) !== '' ? tmc_section('', '<div class="tmc-prose">' . $content . '</div>') : '';
		if (get_post_type() === 'mats') {
			$specs = do_shortcode('[tmc_mat_specs]');
			$aside = '<div class="tmc-m-specs-aside"><p class="tmc-m-eyebrow">Specifications</p><h2 class="tmc-m-h2">Technical details</h2><p class="tmc-m-summary">Not sure this is the right mat for your entrance? Our team can advise on traffic, zones and finishes.</p><p class="tmc-m-more"><a href="' . esc_url(home_url('/mat-finder/')) . '">Try the Mat Finder →</a></p></div>';
			$html .= '<section class="tmc-m-section"><div class="tmc-m-container tmc-m-specs-wrap">' . $aside . $specs . '</div></section>';
			$html .= do_shortcode('[tmc_mat_options][tmc_mat_references][tmc_downloads][tmc_projects][tmc_related]');
		} else {
			$gallery = tmc_gallery_html(tmc_gallery_ids(tmc_field('tmc_gallery_1')), 'accessory', false);
			$html .= tmc_section('Gallery', $gallery, 'Photos');
			$html .= do_shortcode('[tmc_downloads][tmc_related]');
		}
		$busy = false;
		return $html;
	}, 20);
}

/* TMC: Content Styles — styles for the HTML printed by the "TMC: Mat & Accessory Content" shortcodes. Colours and fonts come from the Elementor global variables (--tmc-*). */
.tmc-m-section{padding:112px 24px;background:var(--tmc-white)}
.tmc-m-section--surface{background:var(--tmc-surface)}
.tmc-m-container{max-width:var(--tmc-container,1200px);margin:0 auto}
.tmc-m-head{margin-bottom:48px;max-width:760px}
.tmc-m-eyebrow{display:inline-flex;align-items:center;width:fit-content;margin:0 0 16px;padding:8px 14px;border-radius:999px;background:var(--tmc-sky);font:600 12px/1.2 var(--tmc-font-body);letter-spacing:.14em;text-transform:uppercase;color:var(--tmc-teal-dark)}
.tmc-m-h2{margin:0;font:600 clamp(31px,3.6vw,46px)/1.08 var(--tmc-font-heading);color:var(--tmc-ink);letter-spacing:-.025em}
.tmc-m-h3{margin:0 0 16px;font:600 20px/1.3 var(--tmc-font-heading);color:var(--tmc-ink)}
.tmc-m-summary{margin:0;font:400 18px/1.6 var(--tmc-font-body);color:var(--tmc-muted)}
.tmc-m-more{margin:28px 0 0}
.tmc-m-more a{font:600 15px/1 var(--tmc-font-body);color:var(--tmc-teal-dark);text-decoration:none}
.tmc-m-more a:hover{color:var(--tmc-ink)}


/* Badges & chips */
.tmc-m-chips{display:flex;flex-wrap:wrap;gap:10px;margin:0;padding:0;list-style:none}
.tmc-m-chips{margin-bottom:28px}
.tmc-m-chips li{padding:9px 16px;border-radius:999px;background:var(--tmc-sky);font:600 14px/1 var(--tmc-font-body);color:var(--tmc-teal-dark)}

/* Spec table */
.tmc-m-specs{margin:0;border:1px solid var(--tmc-line);border-radius:var(--tmc-radius);background:var(--tmc-white);overflow:hidden}
.tmc-m-specs>div{display:grid;grid-template-columns:minmax(140px,38%) 1fr;gap:16px;padding:16px 24px;border-top:1px solid var(--tmc-line)}
.tmc-m-specs>div:first-child{border-top:0}
.tmc-m-specs>div:nth-child(even){background:var(--tmc-surface)}
.tmc-m-specs dt{font:500 15px/1.5 var(--tmc-font-body);color:var(--tmc-muted)}
.tmc-m-specs dd{margin:0;font:600 15px/1.5 var(--tmc-font-body);color:var(--tmc-ink)}
.tmc-m-stars{color:var(--tmc-teal);letter-spacing:2px}
.tmc-m-stars span{color:var(--tmc-line)}

/* Galleries */
.tmc-m-gallery{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:16px}
.tmc-m-gallery__item{margin:0}
.tmc-m-gallery__item a{display:block;aspect-ratio:1;border-radius:12px;overflow:hidden;background:var(--tmc-surface)}
.tmc-m-gallery__item img{width:100%;height:100%;object-fit:cover;transition:transform .35s}
.tmc-m-gallery__item a:hover img{transform:scale(1.05)}
.tmc-m-gallery__item figcaption{margin-top:8px;font:500 13px/1.4 var(--tmc-font-body);color:var(--tmc-muted)}
.tmc-m-options{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,7fr);gap:48px;align-items:start}
.tmc-m-options__media img{width:100%;height:auto;border-radius:20px;display:block}
.tmc-m-options__groups{display:flex;flex-direction:column;gap:36px}

/* Downloads */
.tmc-m-downloads{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:14px;margin:0;padding:0;list-style:none}
.tmc-m-downloads a{display:flex;align-items:center;gap:14px;padding:18px 20px;border:1px solid var(--tmc-line);border-radius:12px;background:var(--tmc-white);text-decoration:none;transition:border-color .2s,box-shadow .2s}
.tmc-m-downloads a:hover{border-color:var(--tmc-teal);box-shadow:0 12px 28px rgba(11,26,46,.07)}
.tmc-m-downloads__type{flex-shrink:0;padding:6px 8px;border-radius:6px;background:var(--tmc-sky);font:700 11px/1 var(--tmc-font-body);color:var(--tmc-teal-dark)}
.tmc-m-downloads__name{flex:1;font:600 15px/1.35 var(--tmc-font-body);color:var(--tmc-ink)}
.tmc-m-downloads__go{color:var(--tmc-teal)}

/* Cards */
.tmc-m-cards{display:grid;gap:24px;grid-template-columns:repeat(3,minmax(0,1fr))}
.tmc-m-cards--4{grid-template-columns:repeat(4,minmax(0,1fr))}
.tmc-m-cards--2{grid-template-columns:repeat(2,minmax(0,1fr))}
.tmc-m-card{display:flex;flex-direction:column;border:1px solid var(--tmc-line);border-radius:var(--tmc-radius);background:var(--tmc-white);overflow:hidden;text-decoration:none;transition:box-shadow .25s,transform .25s}
.tmc-m-card:hover{box-shadow:0 22px 44px rgba(11,26,46,.08);transform:translateY(-3px)}
.tmc-m-card__media{display:block;aspect-ratio:4/3;background:var(--tmc-surface);overflow:hidden}
.tmc-m-card__media img{width:100%;height:100%;object-fit:cover;display:block}
.tmc-m-card__ph{display:block;width:100%;height:100%;background:linear-gradient(135deg,var(--tmc-sky),var(--tmc-surface))}
.tmc-m-card__body{display:flex;flex-direction:column;gap:8px;padding:22px 22px 24px;flex:1}
