/**
 * TMC: Mat Finder
 * On the Mat Finder page, the zone/traffic squares link to #finder-a … #finder-f.
 * Clicking one lists every published mat whose "Mat Finder category" field contains
 * that letter, in the element with the class tmc-finder-results.
 * To change which mats appear, tick the mat's Mat Finder category boxes (A–F).
 */
add_action('wp_footer', function () {
	if (!is_page('mat-finder')) return;
	$mats = [];
	foreach (get_posts(['post_type' => 'mats', 'posts_per_page' => -1, 'orderby' => 'menu_order title', 'order' => 'ASC']) as $p) {
		$cats = implode(' ', (array) (function_exists('get_field') ? get_field('tmc_mat_finder', $p->ID, false) : get_post_meta($p->ID, 'tmc_mat_finder', true)));
		preg_match_all('/[A-F]/', strtoupper($cats), $m);
		if (!$m[0]) continue;
		$summary = function_exists('get_field') ? (string) get_field('tmc_summary', $p->ID, false) : '';
		$mats[] = [
			'title' => get_the_title($p),
			'url' => get_permalink($p),
			'img' => (string) get_the_post_thumbnail_url($p, 'medium_large'),
			'text' => wp_trim_words(wp_strip_all_tags($summary), 20),
			'cats' => array_values(array_unique($m[0])),
		];
	}
	$labels = [
		'A' => 'External primary (Zone 1) · Heavy traffic', 'B' => 'External primary (Zone 1) · Moderate traffic',
		'C' => 'Internal primary (Zone 2) · Heavy traffic', 'D' => 'Internal primary (Zone 2) · Moderate traffic',
		'E' => 'Internal circulation (Zone 3) · Heavy traffic', 'F' => 'Internal circulation (Zone 3) · Moderate traffic',
	];
	?>
	<script>
	(function () {
		var mats = <?php echo wp_json_encode($mats); ?>, labels = <?php echo wp_json_encode($labels); ?>;
		var box = document.querySelector('.tmc-finder-results');
		if (!box) return;
		function esc(s) { var d = document.createElement('div'); d.textContent = s; return d.innerHTML; }
		function show(letter, scroll) {
			var list = mats.filter(function (m) { return m.cats.indexOf(letter) > -1; });
			document.querySelectorAll('a[href$="#finder-' + letter.toLowerCase() + '"], a[href*="#finder-"]').forEach(function (a) {
				a.classList.toggle('is-active', a.getAttribute('href').slice(-1).toUpperCase() === letter);
			});
			box.innerHTML = '<p class="tmc-m-eyebrow">Category ' + letter + '</p><h2 class="tmc-m-h2">' + esc(labels[letter]) + '</h2>'
				+ '<p class="tmc-m-summary" style="margin:12px 0 32px">' + list.length + ' suggested mats</p>'
				+ '<div class="tmc-m-cards">' + list.map(function (m) {
					return '<a class="tmc-m-card" href="' + m.url + '"><span class="tmc-m-card__media">' + (m.img ? '<img src="' + m.img + '" alt="" loading="lazy">' : '<span class="tmc-m-card__ph"></span>') + '</span><span class="tmc-m-card__body"><span class="tmc-m-card__title">' + esc(m.title) + '</span>' + (m.text ? '<span class="tmc-m-card__text">' + esc(m.text) + '</span>' : '') + '<span class="tmc-m-card__more">View mat →</span></span></a>';
				}).join('') + '</div>';
			if (scroll) box.scrollIntoView({ behavior: 'smooth', block: 'start' });
		}
		document.addEventListener('click', function (e) {
			var a = e.target.closest('a[href*="#finder-"]');
			if (!a) return;
			e.preventDefault();
			var l = a.getAttribute('href').slice(-1).toUpperCase();
			history.replaceState(null, '', '#finder-' + l.toLowerCase());
			show(l, true);
		});
		var h = (location.hash.match(/finder-([a-f])/i) || [])[1];
		show(h ? h.toUpperCase() : 'A', !!h);
	})();
	</script>
	<?php
}, 30);

/**
 * TMC: Technical Table
 * On the Technical Information page (and the Solutions page, which adds supplier and price), fills the element with the class tmc-tech-results
 * with a filterable table of every published mat (filters: mat type, height).
 * Data comes from each mat's ACF "Mat Details" fields.
 */
add_action('wp_footer', function () {
	if (!is_page(['technical-information', 'solutions'])) return;
	$full = is_page('solutions');
	$raw = function ($name, $id) { return function_exists('get_field') ? get_field($name, $id, false) : get_post_meta($id, $name, true); };
	$rows = [];
	foreach (get_posts(['post_type' => 'mats', 'posts_per_page' => -1, 'orderby' => 'menu_order title', 'order' => 'ASC']) as $p) {
		$terms = get_the_terms($p->ID, 'mat-categories');
		$rows[] = [
			'title' => get_the_title($p),
			'url' => get_permalink($p),
			'cat' => $terms && !is_wp_error($terms) ? $terms[0]->name : '',
			'type' => trim((string) $raw('tmc_type', $p->ID)),
			'height' => array_values(array_filter((array) $raw('tmc_height', $p->ID))),
			'wear' => implode(', ', array_filter((array) $raw('tmc_wear', $p->ID))),
			'guarantee' => (string) $raw('tmc_guarantee', $p->ID),
			'fire' => (string) $raw('tmc_fire_rating', $p->ID),
			'supplier' => $full ? trim((string) $raw('tmc_supplier', $p->ID)) : '',
			'price' => $full ? str_repeat('€', (int) $raw('tmc_cost', $p->ID)) : '',
		];
	}
	?>
	<script>
	(function () {
		var rows = <?php echo wp_json_encode($rows); ?>, full = <?php echo $full ? 'true' : 'false'; ?>;
		var box = document.querySelector('.tmc-tech-results');
		if (!box) return;
		function esc(s) { var d = document.createElement('div'); d.textContent = s || ''; return d.innerHTML; }
		function uniq(a) { return a.filter(function (v, i) { return v && a.indexOf(v) === i; }); }
		var types = uniq(rows.map(function (r) { return r.type; })).sort();
		var suppliers = uniq(rows.map(function (r) { return r.supplier; })).sort();
		var heights = uniq([].concat.apply([], rows.map(function (r) { return r.height; }))).sort(function (a, b) { return parseFloat(a) - parseFloat(b); });
		box.innerHTML = '<div class="tmc-tech-filters"><label>Mat type<select data-f="type"><option value="">All mat types</option>' + types.map(function (t) { return '<option>' + esc(t) + '</option>'; }).join('') + '</select></label>'
			+ (full ? '<label>Supplier<select data-f="supplier"><option value="">All suppliers</option>' + suppliers.map(function (t) { return '<option>' + esc(t) + '</option>'; }).join('') + '</select></label>' : '')
			+ '<label>Height<select data-f="height"><option value="">All heights</option>' + heights.map(function (h) { return '<option>' + esc(h) + '</option>'; }).join('') + '</select></label>'
			+ '<p class="tmc-tech-count" aria-live="polite"></p></div><div class="tmc-tech-wrap"><table class="tmc-tech"><thead><tr><th>Mat</th><th>Range</th><th>Height</th><th>Traffic</th><th>Fire rating</th><th>Guarantee</th>' + (full ? '<th>Supplier</th><th>Price</th>' : '') + '<th></th></tr></thead><tbody></tbody></table></div>';
		var body = box.querySelector('tbody'), count = box.querySelector('.tmc-tech-count');
		function draw() {
			var t = box.querySelector('[data-f=type]').value, h = box.querySelector('[data-f=height]').value, sp = full ? box.querySelector('[data-f=supplier]').value : '';
			var list = rows.filter(function (r) { return (!t || r.type === t) && (!h || r.height.indexOf(h) > -1) && (!sp || r.supplier === sp); });
			count.textContent = list.length + ' of ' + rows.length + ' mats';
			body.innerHTML = list.map(function (r) {
				return '<tr><td data-l="Mat"><a href="' + r.url + '">' + esc(r.title) + '</a></td><td data-l="Range">' + esc(r.cat) + '</td><td data-l="Height">' + esc(r.height.join(', ')) + '</td><td data-l="Traffic">' + esc(r.wear) + '</td><td data-l="Fire rating">' + esc(r.fire) + '</td><td data-l="Guarantee">' + esc(r.guarantee) + '</td>' + (full ? '<td data-l="Supplier">' + esc(r.supplier) + '</td><td data-l="Price">' + esc(r.price) + '</td>' : '') + '<td><a class="tmc-tech-link" href="' + r.url + '">Technical specs →</a></td></tr>';
			}).join('') || '<tr><td colspan="9">No mats match these filters.</td></tr>';
		}
		box.addEventListener('change', draw);
		draw();
	})();
	</script>
	<?php
}, 30);

